"""sem_augment: add synthetic training rows, generated by LLM-written code.

What the operator does
    ``DataOp.sem_augment(nl_prompt, number_of_rows_to_generate, name, generate_via_code=True)`` asks the LLM to write
    an ``augment_data(df)`` function. The function typically fits a synthesizer from the ``sdv`` library and appends
    ``number_of_rows_to_generate`` synthetic rows. With ``generate_via_code=False`` the LLM writes the rows itself as
    JSON instead. Augmentation only happens while the pipeline is *fitted* (``fit``/``fit_transform``). At
    prediction time the operator lets the data pass through unchanged, so test rows are never altered.

What this example shows
    We train a salary regressor on only 1000 employees of skrub's ``employee_salaries`` data. We then add 500
    synthetic employees and compare the R² on the official held-out test split (1228 employees) before and after
    augmentation. Synthetic data does not always help. Watch whether it does here.

How to run (from the repository root)
    poetry run python examples/09_sem_augment.py

Runtime / cost
    About 1-3 minutes (fitting the synthesizer dominates). 1 LLM call to generate the augmentation code, plus
    retries if the generated code fails validation.
"""

import skrub
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.metrics import r2_score

import sempipes  # importing sempipes adds the .sem_* methods to skrub DataOps

N_TRAIN, N_SYNTHETIC = 1000, 500


def build_pipeline(augment: bool) -> skrub.DataOp:
    salaries = skrub.var("salaries")  # the full table, target column included

    if augment:
        # Augment the *joint* table so that every synthetic employee also gets a (synthetic) salary.
        salaries = salaries.sem_augment(
            nl_prompt="Generate realistic additional employees to improve the prediction of 'current_annual_salary'. "
            "Keep the relationships between department, position title, hiring year and salary consistent, "
            "keep categorical values valid and avoid duplicate rows.",
            number_of_rows_to_generate=N_SYNTHETIC,
            name="augment_salaries",
            generate_via_code=True,
        )

    # errors="ignore": at prediction time the input table has no salary column to drop.
    X = salaries.drop(columns="current_annual_salary", errors="ignore").skb.mark_as_X()
    y = salaries["current_annual_salary"].skb.mark_as_y()
    return X.skb.apply(skrub.TableVectorizer()).skb.apply(HistGradientBoostingRegressor(random_state=0), y=y)


def main() -> None:
    train = skrub.datasets.fetch_employee_salaries(split="train").employee_salaries.sample(n=N_TRAIN, random_state=0)
    test = skrub.datasets.fetch_employee_salaries(split="test")

    for augment in (False, True):
        pipeline = build_pipeline(augment)
        env = pipeline.skb.get_data()  # default values of SemPipes' hidden helper variables
        learner = pipeline.skb.make_learner()
        learner.fit({**env, "salaries": train})  # sem_augment generates and runs its code here
        predictions = learner.predict({**env, "salaries": test.X})  # no augmentation at prediction time

        rows = f"{N_TRAIN} real + {N_SYNTHETIC} synthetic" if augment else f"{N_TRAIN} real"
        print(f"=== {'With' if augment else 'Without'} augmentation ({rows} training rows) ===")
        print(f"Test R²: {r2_score(test.y, predictions):.3f}\n")


if __name__ == "__main__":
    main()
